#include <stdlib.h>

// Definition of a singly linked list node
typedef struct Node {
    int data;
    struct Node* next;
} Node;

// Function to reverse a singly linked list in place
void reverseInPlace(Node* head) {
    // Initialize pointers for the previous and current nodes
    Node* prev = NULL;
    Node* current = head;
    Node* next = NULL;

    // Traverse the list until the end
    while (current != NULL) {
        // Store the next node in the next pointer
        next = current->next;

        // Reverse the link from the current node to the next node
        current->next = prev;

        // Move the previous and current nodes one step forward
        prev = current;
        current = next;
    }

    // Set the head of the list to the previous node
    head = prev;
}

// Function to check the correctness of the reverseInPlace function
